#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <chrono>
#include <vector>
#include <string>
#include <algorithm>
#include "../backprop-cuda/backprop.h"
#include "native_reference_repaired.cuh"
#include "../backprop-cuda/bpnn_adjust_weights.h"
struct Net{int n;std::vector<float>x,w,prev,hw,hp,target,h,o,hd,od;Net(int N,int f):n(N),x(N+1),w((N+1)*17),prev(w.size()),hw(34),hp(34),target({0,.2f+.5f*(f-1)}),h(17),o(2),hd(17),od(2){x[0]=1;for(int i=1;i<=n;i++)x[i]=((i*13+f*7)%31-15)/32.f;for(int i=0;i<=n;i++)for(int j=0;j<=16;j++){w[i*17+j]=((i*11+j*7+f*3)%37-18)/128.f;prev[i*17+j]=((i*5+j*3)%17-8)/1024.f;}for(int i=0;i<=16;i++)for(int j=0;j<=1;j++){hw[i*2+j]=((i*7+j*11+f)%29-14)/64.f;hp[i*2+j]=((i*3+j)%13-6)/1024.f;}}};
void add(std::vector<float>&a,const std::vector<float>&b){a.insert(a.end(),b.begin(),b.end());}
std::vector<double>oracle(const Net&z){int n=z.n;std::vector<double>w(z.w.begin(),z.w.end()),p(z.prev.begin(),z.prev.end()),hw(z.hw.begin(),z.hw.end()),hp(z.hp.begin(),z.hp.end()),h(17),o(2),hd(17),od(2),out;h[0]=1;for(int j=1;j<=16;j++){double s=0;for(int i=0;i<=n;i++)s+=w[i*17+j]*z.x[i];h[j]=1/(1+exp(-s));}double s=0;for(int j=0;j<=16;j++)s+=hw[j*2+1]*h[j];o[1]=1/(1+exp(-s));od[1]=o[1]*(1-o[1])*(z.target[1]-o[1]);for(int j=1;j<=16;j++)hd[j]=h[j]*(1-h[j])*od[1]*hw[j*2+1];for(int i=0;i<=n;i++)for(int j=1;j<=16;j++){double u=(double)ETA*hd[j]*z.x[i]+(double)MOMENTUM*p[i*17+j];w[i*17+j]+=u;p[i*17+j]=u;}for(int i=0;i<=16;i++){double u=(double)ETA*od[1]*h[i]+(double)MOMENTUM*hp[i*2+1];hw[i*2+1]+=u;hp[i*2+1]=u;}for(auto*a:{&w,&p,&h,&o,&hd,&od,&hw,&hp})out.insert(out.end(),a->begin(),a->end());out.push_back(fabs(od[1]));double eh=0;for(double d:hd)eh+=fabs(d);out.push_back(eh);return out;}
std::pair<std::vector<float>,double>train(Net z){int n=z.n;std::vector<float>partial(n),got(z.w.size()),gp(z.w.size());cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();float *di,*dw,*dp,*dd,*dprev;cudaMalloc(&di,(n+1)*4);cudaMalloc(&dw,z.w.size()*4);cudaMalloc(&dp,n*4);cudaMemcpy(di,z.x.data(),(n+1)*4,cudaMemcpyHostToDevice);cudaMemcpy(dw,z.w.data(),z.w.size()*4,cudaMemcpyHostToDevice);kernel_layerforward<<<dim3(1,n/16),dim3(16,16)>>>(di,dw,dp,16);cudaMemcpy(partial.data(),dp,n*4,cudaMemcpyDeviceToHost);for(int j=1;j<=16;j++){float s=0;for(int k=0;k<n/16;k++)s+=partial[k*16+j-1];s+=z.w[j];z.h[j]=(float)(1.0/(1.0+exp(-(double)s)));}z.h[0]=1;float sum=0;for(int i=0;i<=16;i++)sum+=z.hw[i*2+1]*z.h[i];z.o[1]=(float)(1.0/(1.0+exp(-(double)sum)));float o=z.o[1],target=z.target[1];z.od[1]=o*(1.0-o)*(target-o);float eo=fabsf(z.od[1]),eh=0;for(int j=1;j<=16;j++){float h=z.h[j];float s=z.od[1]*z.hw[j*2+1];z.hd[j]=h*(1.0-h)*s;eh+=fabsf(z.hd[j]);}for(int i=0;i<=16;i++){float u=ETA*z.od[1]*z.h[i]+MOMENTUM*z.hp[i*2+1];z.hw[i*2+1]+=u;z.hp[i*2+1]=u;}cudaMemcpy(dw,z.w.data(),z.w.size()*4,cudaMemcpyHostToDevice);cudaMalloc(&dd,17*4);cudaMalloc(&dprev,z.prev.size()*4);cudaMemcpy(dd,z.hd.data(),17*4,cudaMemcpyHostToDevice);cudaMemcpy(dprev,z.prev.data(),z.prev.size()*4,cudaMemcpyHostToDevice);kernel_adjust_weights<<<dim3(1,n/16),dim3(16,16)>>>(di,dw,dd,dprev,16);cudaMemcpy(got.data(),dw,got.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(gp.data(),dprev,gp.size()*4,cudaMemcpyDeviceToHost);cudaFree(di);cudaFree(dw);cudaFree(dp);cudaFree(dd);cudaFree(dprev);cudaDeviceSynchronize();double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count();add(got,gp);for(auto*a:{&z.h,&z.o,&z.hd,&z.od,&z.hw,&z.hp})add(got,*a);got.push_back(eo);got.push_back(eh);return {got,elapsed};}
int main(){std::vector<Net>nets={Net(64,1),Net(96,2)};std::vector<double>gold;std::vector<float>prefix;for(auto&n:nets){auto g=oracle(n);gold.insert(gold.end(),g.begin(),g.end());for(auto*a:{&n.x,&n.w,&n.prev,&n.hw,&n.hp,&n.target})add(prefix,*a);train(n);}for(int trial=1;trial<=5;trial++){std::vector<float>got;double elapsed=0;for(auto&n:nets){auto v=train(n);add(got,v.first);elapsed+=v.second;}bool ok=cudaGetLastError()==cudaSuccess;double err=0;for(size_t i=0;i<got.size();i++){err=std::max(err,fabs(got[i]-gold[i]));ok&=std::isfinite(got[i]);}ok&=err<1e-5;auto artifact=prefix;add(artifact,got);const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(artifact.data(),4,artifact.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":0.0,\"timing_region\":\"two_fresh_full_training_steps_host_inclusive\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",got.size(),err,path.c_str(),artifact.size());if(!ok)return 2;}}
